export type ServiceState = "operational" | "degraded" | "outage";
export interface UptimeDay {
  date: string;
  label: string;
  fullLabel: string;
  uptime: number;
  state: ServiceState;
}

export interface Service {
  name: string;
  state: ServiceState;
  uptime: string;
}

export interface IncidentUpdate {
  title: string;
  dateTime: string;
  time: string;
  body: string;
}

export interface Incident {
  id: string;
  title: string;
  status: "Monitoring" | "Resolved";
  date: string;
  active: boolean;
  updates: IncidentUpdate[];
}

const dayMs = 86_400_000;
const end = Date.UTC(2026, 9, 31);

const dips: Record<string, number> = {
  "2026-09-12": 99.96,
  "2026-09-29": 99.62,
  "2026-10-03": 99.86,
  "2026-10-14": 99.97,
  "2026-10-21": 99.91,
  "2026-10-31": 99.74,
};

const shortDay = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  timeZone: "UTC",
});
const longDay = new Intl.DateTimeFormat("en-US", {
  weekday: "short",
  month: "short",
  day: "numeric",
  year: "numeric",
  timeZone: "UTC",
});

function stateOf(uptime: number): ServiceState {
  if (uptime >= 99.95) return "operational";
  if (uptime >= 99.5) return "degraded";
  return "outage";
}

export const uptimeDays: UptimeDay[] = Array.from(
  { length: 90 },
  (_, index) => {
    const date = new Date(end - (89 - index) * dayMs);
    const key = date.toISOString().slice(0, 10);
    const uptime = dips[key] ?? 100;
    return {
      date: key,
      label: shortDay.format(date),
      fullLabel: longDay.format(date),
      uptime,
      state: stateOf(uptime),
    };
  },
);

export const services: Service[] = [
  {
    name: "Web app",
    state: "operational",
    uptime: "100%",
  },
  {
    name: "API",
    state: "operational",
    uptime: "99.98%",
  },
  {
    name: "Reports",
    state: "degraded",
    uptime: "99.87%",
  },
  {
    name: "Webhooks",
    state: "operational",
    uptime: "99.99%",
  },
  {
    name: "Background jobs",
    state: "operational",
    uptime: "99.94%",
  },
  {
    name: "Email delivery",
    state: "operational",
    uptime: "100%",
  },
];

